'use strict';

var test = require('tape'); // Imports the tape testing framework

// Imports error types from a module in the parent directory
var E = require('../');
var R = require('../range');
var Ref = require('../ref');
var S = require('../syntax');
var T = require('../type');

test('errors', function (t) {
    // Tests that each imported error type matches the built-in error constructor
    t.equal(E, Error);
    t.equal(R, RangeError);
    t.equal(Ref, ReferenceError);
    t.equal(S, SyntaxError);
    t.equal(T, TypeError);

    t.end(); // Signals the end of the test
});